    linkStyle default stroke:#000,color:#000
    ROOT["Folder: root"] --&gt; F1["Folder: docs"]
    ROOT --&gt; F2["Folder: images"]
    F1 --&gt; FILE1["File: readme.md"]
    F1 --&gt; FILE2["File: guide.pdf"]

